import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";
import type { ComparisonManifest, FileAnalysis } from "@diffkin/protocol";

// Generated by `cargo run -p diffkin-analysis --example ui_fixture` from the actual Rust engine.
const input = process.env.DIFFKIN_KERNEL_FIXTURE;
if (input) {
  const capture = JSON.parse(readFileSync(input, "utf8")) as {
    manifest: ComparisonManifest;
    files: FileAnalysis[];
  };
  for (const file of capture.files) {
    const isFormat = file.file.summary.path.startsWith("format/");
    test(`real kernel ${isFormat ? "formatting" : "movement and internal edits"} renders for ${file.file.summary.path}`, async ({
      page,
    }) => {
      const movement = file.analysis?.events.find(
        (event) => event.facets.includes("move") && event.facets.includes("edit"),
      );
      if (!isFormat) {
        expect(
          movement,
          "fixture must exercise movement together with a semantic edit",
        ).toBeTruthy();
        expect(movement!.children.length).toBeGreaterThan(0);
      } else {
        expect(file.analysis!.coverage.length).toBeGreaterThan(0);
        expect(
          file.analysis!.coverage.every((entry) => entry.presentation === "folded-format"),
        ).toBe(true);
      }
      await page.addInitScript(
        ({ manifest, file }) => {
          Object.defineProperty(window, "isTauri", { value: true });
          Object.defineProperty(window, "__TAURI_INTERNALS__", {
            value: {
              invoke: async (command: string) => {
                if (command === "open_comparison")
                  return { ...manifest, files: [file.file.summary], totalFiles: 1 };
                if (command === "request_file") return file;
                if (command === "cancel_job") return;
                throw new Error(`Unexpected command ${command}`);
              },
            },
          });
        },
        { manifest: capture.manifest, file },
      );
      await page.goto("/");
      await page.getByLabel("Git 仓库路径").fill("/kernel-fixture");
      await page.getByRole("button", { name: "打开比较", exact: true }).click();
      if (isFormat) {
        await expect(page.locator(".cm-foldPlaceholder").first()).toBeVisible();
        await expect(page.locator(".merge-host")).not.toContainText("return x + 1", {
          useInnerText: true,
        });
        await page.getByRole("button", { name: "完整原始视图", exact: true }).click();
        await expect(page.locator(".merge-host")).toContainText("return (x+1)");
        await expect(page.locator(".merge-host")).toContainText("return x + 1");
        await page.getByRole("button", { name: "统一", exact: true }).click();
        await expect(page.locator(".merge-host")).toContainText("return (x+1)");
        await page.getByRole("button", { name: "收起格式", exact: true }).click();
        await expect(page.locator(".merge-host")).not.toContainText("return (x+1)", {
          useInnerText: true,
        });
        return;
      }
      await expect(page.locator(".move-overlay path")).toHaveAttribute("d", /^M .+ C .+/);
      const group = page.getByRole("group", { name: movement!.title, exact: true });
      await expect(group.locator(".event.child")).toHaveCount(movement!.children.length);
      await group.locator(".event.child").first().click();
      await expect(page.getByLabel("仅对照这组变化")).toBeChecked();
      await expect(page.locator(".merge-host")).toContainText("available");
      await expect(page.locator(".merge-host")).toContainText(">=");
      await expect(page.locator(".merge-host")).not.toContainText("audit");
      await expect(page.getByRole("alert")).toHaveCount(0);
      await page.getByRole("button", { name: "统一", exact: true }).click();
      await expect(page.locator(".merge-host")).toContainText(">=");
      await expect(page.locator(".cm-deletedChunk")).toBeVisible();
    });
  }
}
